// App members. Comparison is transient, account-bound and decoded by ImageWorker.
fs::path auditionCompareReference;std::string auditionCompareReferenceRun,auditionCompareScope,auditionCompareChannel,auditionCompareMode;int auditionCompareReferenceIndex=-1;
fs::path auditionComparePaths[4];Com<ID2D1Bitmap> auditionCompareBitmaps[4];bool auditionCompareFailed[4]={};bool auditionCompareNearest[4]={};std::vector<std::pair<std::string,int>> auditionPickSet;float auditionImagePercent=0;ULONGLONG auditionCompareNextCheck=0;
void stopAuditionComparison(bool clearReference=false){for(int i=0;i<4;i++){auditionComparePaths[i].clear();auditionCompareBitmaps[i].Reset();auditionCompareFailed[i]=false;}if(clearReference){auditionCompareReference.clear();auditionCompareReferenceRun.clear();auditionCompareReferenceIndex=-1;auditionPickSet.clear();}}
void checkAuditionComparison(){if(auditionCompareScope!=store->workspaceScope||auditionCompareChannel!=store->active||auditionCompareMode!=str(store->settings,"content_mode","standard"))stopAuditionComparison(true);if(GetTickCount64()>=auditionCompareNextCheck){auditionCompareNextCheck=GetTickCount64()+1000;for(auto& path:auditionComparePaths)if(!path.empty()){std::error_code error;if(!fs::is_regular_file(path,error))stopAuditionComparison();}}}
bool auditionComparing(){checkAuditionComparison();int n=0;for(auto& path:auditionComparePaths)n+=!path.empty();return n>=2;}
void beginAuditionComparison(const fs::path& a,const fs::path& b){beginAuditionComparison(std::vector<fs::path>{a,b});}
void beginAuditionComparison(const std::vector<fs::path>& list){if(list.size()<2||list.size()>4)throw std::runtime_error("비교는 2~4개 후보만 가능합니다.");for(auto& path:list)if(!fs::is_regular_file(path)||!localOutputAllowed(store->settings,path)||!localImageVisible(store->settings,path)||(!hardcore()&&imageIsHardcore(store->settings,path)))throw std::runtime_error("현재 계정과 모드의 후보 이미지를 선택하세요.");stopAuditionComparison();auditionCompareScope=store->workspaceScope;auditionCompareChannel=store->active;auditionCompareMode=str(store->settings,"content_mode","standard");for(size_t i=0;i<list.size();i++)auditionComparePaths[i]=list[i];focusPreview=true;images.compareMany(list,revision);InvalidateRect(hwnd,nullptr,FALSE);}
std::pair<Rect,Rect> auditionComparisonPanes(Rect r){float x=r.x+8,y=r.y+34,w=std::max(1.f,r.w-16),h=std::max(1.f,r.h-42);if(r.w>=420){float half=(w-8)/2;return {{x,y,half,h},{x+half+8,y,half,h}};}float half=std::max(1.f,(h-8)/2);return {{x,y,w,half},{x,y+half+8,w,half}};}
std::vector<Rect> auditionComparisonLayout(Rect r,size_t n){std::vector<Rect> out;if(n<=2){auto p=auditionComparisonPanes(r);out.push_back(p.first);if(n>1)out.push_back(p.second);return out;}float x=r.x+8,y=r.y+34,w=std::max(1.f,r.w-16),h=std::max(1.f,r.h-42);size_t cols=r.w>=420?2:1,rows=(n+cols-1)/cols;float cw=std::max(1.f,(w-8*(cols-1))/cols),ch=std::max(1.f,(h-8*(rows-1))/rows);for(size_t i=0;i<n;i++)out.push_back({x+(i%cols)*(cw+8),y+(i/cols)*(ch+8),cw,ch});return out;}
bool paintAuditionComparison(Rect area){if(!auditionComparing())return false;std::vector<int> slots;for(int i=0;i<4;i++)if(!auditionComparePaths[i].empty())slots.push_back(i);auto panes=auditionComparisonLayout(area,slots.size());label(L"후보 비교 ("+std::to_wstring(slots.size())+L"개)",{area.x+10,area.y+5,std::max(1.f,area.w-90),24},true);button({area.x+area.w-74,area.y+4,66,24},L"비교 종료",[this]{stopAuditionComparison();});for(size_t k=0;k<slots.size();k++){int i=slots[k];auto pane=panes[k];renderer.box(pane,0x141415,0x3a3a40,5);label(std::wstring(1,wchar_t(L'A'+k)),{pane.x+6,pane.y+2,pane.w-12,18},true);Rect image{pane.x+4,pane.y+23,std::max(1.f,pane.w-8),std::max(1.f,pane.h-27)};if(auditionCompareBitmaps[i])renderer.bitmap(auditionCompareBitmaps[i].Get(),image,auditionCompareNearest[i]);else label(auditionCompareFailed[i]?L"읽기 실패":L"불러오는 중…",image,false,0xccccd0,11);}return true;}
void auditionShowProgress(){checkAuditionComparison();if((!auditionRunning&&!auditionInFlight)||!auditionData||auditionRun.empty()||auditionScope!=store->workspaceScope||auditionChannel!=store->active)return;auto& row=auditionData->run(auditionRun);int done=0;for(auto& item:row["tasks"])done+=str(item,"state")=="completed";auto total=row["tasks"].size();auto prefix=L"[오디션 ";if(status.rfind(prefix,0)==0){auto end=status.find(L"] ");if(end!=std::wstring::npos)status=status.substr(end+2);}status=std::wstring(prefix)+std::to_wstring(done)+L"/"+std::to_wstring(total)+L"] "+status;if(total)progress=float(100.*(done+std::clamp(auditionImagePercent,0.f,99.f)/100)/total);}
